import 'package:flutter/material.dart';
import '../services/match_service.dart';
import '../theme/app_theme.dart';
class CouponScreen extends StatefulWidget { const CouponScreen({super.key}); @override State<CouponScreen> createState()=>_CouponScreenState(); }
class _CouponScreenState extends State<CouponScreen>{ final Map<int,Set<String>> picks={}; int get columns{var n=1; for(final m in MatchService.matches){n*=picks[m.number]?.length??1;} return n;} void toggle(int n,String x){setState((){final s=picks.putIfAbsent(n,()=>{}); if(s.contains(x))s.remove(x);else s.add(x);});}
 @override Widget build(BuildContext context)=>SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,22,20,10),child:Row(children:[const Expanded(child:Text('Kupon Oluştur',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900))),IconButton(onPressed:()=>setState(picks.clear),icon:const Icon(Icons.refresh))])),Expanded(child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,8,16,120),itemCount:15,itemBuilder:(c,i){final m=MatchService.matches[i];final s=picks[m.number]??{};return Card(margin:const EdgeInsets.only(bottom:8),child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[Row(children:[Text('${m.number.toString().padLeft(2,'0')}',style:const TextStyle(color:AppTheme.green,fontWeight:FontWeight.w900)),const SizedBox(width:10),Expanded(child:Text('${m.home}  —  ${m.away}',style:const TextStyle(fontWeight:FontWeight.bold))),Text(m.time,style:const TextStyle(color:Colors.white54,fontSize:11))]),const SizedBox(height:10),Row(children:['1','X','2'].map((x)=>Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:3),child:ChoiceChip(label:Center(child:Text(x)),selected:s.contains(x),onSelected:(_)=>toggle(m.number,x)))).toList())]))); })),Align(alignment:Alignment.bottomCenter,child:Container(padding:const EdgeInsets.fromLTRB(20,12,20,20),decoration:const BoxDecoration(color:Color(0xFF0D141A)),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$columns Kolon',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const Text('Tutar: hesaplama için güncel resmi fiyat gerekir',style:TextStyle(color:Colors.white54,fontSize:11))])),FilledButton.icon(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Kupon hazırlandı.'))),icon:const Icon(Icons.check),label:const Text('Kaydet'))]))])); }
